package io.todu.andjs.domain

object AutomationApiCatalog {
    val methods=listOf(
        ApiMethod("system.openApp",ApiCategory.DEVICE,"andjs.system","andjs.system.openApp(packageName)","按包名打开本机应用。",listOf(ApiArgument("packageName","string","目标应用的完整包名，例如 com.android.settings。不是应用名称。")),"boolean。成功发起启动返回 true，不代表目标应用已完成加载。应用未安装、已停用、没有启动入口或系统拒绝时抛错。手机和手表均只打开本机应用；手机手表预览打开的是手机应用。受系统后台启动限制，建议在脚本最后调用；离开 And JS 后按后台规则停止脚本。","andjs.system.openApp(\"com.android.settings\");","可用 · 受系统限制"),
        ApiMethod("notes.get",ApiCategory.STORAGE,"andjs.notes","andjs.notes.get(number)","读取便签内容。",listOf(ApiArgument("number","number","便签编号，1–4 的整数。")),"string。空便签返回空字符串。读取本机便签，预览与手机隔离。","exit(andjs.notes.get(1));","可用"),
        ApiMethod("notes.set",ApiCategory.STORAGE,"andjs.notes","andjs.notes.set(number, text)","修改便签内容。",listOf(ApiArgument("number","number","便签编号，1–4 的整数。"),ApiArgument("text","string","最多 4000 字符，空字符串清空便签。")),"boolean。保存成功返回 true，参数错误或保存失败时抛错。手机修改后需手动同步到手表；手表修改仅保存在本机，下次手机同步会覆盖。预览修改与手机隔离，刷新预览会重新加载手机便签。","andjs.notes.set(1, \"今天的安排\");","可用"),
        ApiMethod("ui.close",ApiCategory.UI,"andjs.ui","andjs.ui.close()","关闭当前脚本运行窗口。",emptyList(),"不返回。立即停止本次执行并关闭运行窗口，后续代码不再执行；音频、网络请求等资源随运行释放。子脚本调用时关闭整个调用链的运行窗口。手表返回脚本列表；手机桌面悬浮窗直接关闭。","andjs.ui.close();","可用"),
        ApiMethod("util.qr",ApiCategory.UTILITIES,"andjs.util","andjs.util.qr(text)","生成二维码图片。",listOf(ApiArgument("text","string","非空文本，UTF-8 编码最多 2000 字节；支持中文和链接。")),"string。PNG Data URL（data:image/png;base64,...），约 320×320 像素，含白色静区。可直接传给 andjs.log.img；不产生临时文件。","const qr = andjs.util.qr(\"https://example.com\");\nandjs.log.img(qr, \"100%\");\n// 保存 PNG\nandjs.files.write(\"app:/qr.png\", qr.split(\",\")[1], \"base64\");","可用"),
        ApiMethod("system.openUrl",ApiCategory.DEVICE,"andjs.system","andjs.system.openUrl(url)","打开网页、地图或应用链接。",listOf(ApiArgument("url","string","带协议的链接，最多 8192 字符；例如 https://example.com、geo:31.23,121.47。支持应用自定义协议，不支持 file/content/javascript/intent 协议。")),"boolean。成功发起打开操作返回 true；没有对应应用或系统拒绝时抛错。不会等待目标应用关闭。手机和手表均需本机安装能处理链接的应用；离开 And JS 后按后台规则停止当前脚本，建议放在最后执行。","andjs.system.openUrl(\"geo:31.23,121.47?q=31.23,121.47\");","可用 · 取决于本机应用"),
        ApiMethod("clipboard.get",ApiCategory.DEVICE,"andjs.clipboard","andjs.clipboard.get()","读取系统剪贴板文字。",emptyList(),"string | null。读取第一项文字；剪贴板为空或系统不允许读取时返回 null。Android 限制后台读取，桌面悬浮运行可能无法读取。手表需系统支持剪贴板，不会读取手机剪贴板。","const text = andjs.clipboard.get();\nexit(text);","可用 · 受系统限制"),
        ApiMethod("clipboard.set",ApiCategory.DEVICE,"andjs.clipboard","andjs.clipboard.set(text)","写入系统剪贴板。",listOf(ApiArgument("text","string","最多 100 万字符，空字符串用于覆盖现有文字。")),"boolean。写入成功返回 true；系统拒绝时抛错。","andjs.clipboard.set(\"复制的内容\");","可用"),
        ApiMethod("system.share",ApiCategory.DEVICE,"andjs.system","andjs.system.share(textOrFile)","通过系统菜单分享文字或文件。",listOf(ApiArgument("textOrFile","string","普通字符串作为文本；以 app:/ 或 shared:/ 开头作为文件路径。文件最多 32MB，共享存储仅手机且需授权。对象先 JSON.stringify；下载响应使用 app:/network/ 加 file 字段。")),"boolean。成功打开分享菜单返回 true，不代表用户完成分享。没有可处理应用或文件无效时抛错。手表取决于是否安装支持分享的应用。文件复制到独立临时目录，避免脚本结束清理下载文件后无法分享；每次分享或打开应用时清理超过 24 小时的副本，总量最多 64MB，不在后台运行清理任务。离开应用后按后台规则停止脚本。","andjs.system.share(\"结果文字\");\n// 或分享本地图片\n// andjs.system.share(\"app:/qr.png\");","可用 · 取决于本机应用"),
        ApiMethod("cache.get",ApiCategory.STORAGE,"andjs.cache","andjs.cache.get(key, defaultValue)","读取未过期的缓存。",listOf(ApiArgument("key","string","1–200 字符，区分大小写。"),ApiArgument("defaultValue","JSON 值，可选","不存在或已过期时返回，默认 null。")),"JSON 值。保留字符串、数字、布尔、对象、数组或 null 类型；false、0、空字符串不会触发默认值。缓存为本机脚本共享的独立空间，不随手表同步；预览缓存与手机隔离。过期项在打开应用或调用缓存接口时清理，无后台定时任务。","exit(andjs.cache.get(\"weather\", {}));","可用"),
        ApiMethod("cache.set",ApiCategory.STORAGE,"andjs.cache","andjs.cache.set(key, value, ttl)","保存带有效期的缓存。",listOf(ApiArgument("key","string","1–200 字符。"),ApiArgument("value","JSON 值","支持字符串、有限数字、布尔、对象、数组和 null。不要传函数、undefined 或循环引用。"),ApiArgument("ttl","number，可选","有效期秒数，默认 3600；大于 0 且不超过 31536000，支持小数。覆盖时重新计时，使用设备系统时钟。")),"boolean。成功返回 true，写入失败或超限抛错。最多 256 项，总文件不超过 1MB，重启仍保留；不会同步到另一设备。","andjs.cache.set(\"weather\", {temperature: 26}, 600);","可用"),
        ApiMethod("cache.remove",ApiCategory.STORAGE,"andjs.cache","andjs.cache.remove(key)","删除缓存项。",listOf(ApiArgument("key","string","缓存键。")),"boolean。删除未过期项目返回 true；不存在或已过期返回 false。","andjs.cache.remove(\"weather\");","可用"),
        ApiMethod("script.run",ApiCategory.SCRIPTS,"andjs.script","andjs.script.run(id, params)","同步调用另一个脚本并取得返回值。",listOf(ApiArgument("id","string","编辑页面代码/参数右侧显示脚本 ID 的前 8 位，点击可复制完整 ID。手机调用已保存脚本；手表只能调用已同步脚本，不依赖手机。"),ApiArgument("params","object，可选","按键覆盖被调用脚本本次参数，通过 andjs.value.get 读取；值支持 boolean/string/number/array。省略的键沿用已保存参数。传入本身不会保存；子脚本调用 value.set/delete 时会保存该次参数。")),"返回子脚本 exit(value) 的原始值，包括 true、false、null、对象和数组；无 exit 或 exit() 返回 undefined。子脚本 exit 只结束子脚本；异常传回调用方，可 try/catch。子脚本作用域独立；全局变量修改对父脚本立即可见。日志合并实时显示，共用停止信号、运行时间、内存及日志限额，最多嵌套 8 层。界面交互仍会等待用户。","const result = andjs.script.run(\"目标脚本ID\", {name: \"朋友\"});\nexit(result);\n// 目标脚本：exit({hello: andjs.value.get(\"name\")});","可用")
    )
}
